@@ -0,0 +1,53 @@
+using Pitt.Production;
+using UnityEngine;
+
+namespace Pitt.OnePit
+{
+    /// NB120: retain old IDs and op.core records for included steps.
+    public static class V6nProdFlow
+    {
+        public const float WhipSeconds = 0.25f, ForsageMultiplier = 6f;
+        public static bool Enabled => OnePitBalance.FlowV3 && HallRowDefs.MergedAuto;
+
+        public static bool ForsageHost(IBenchHost h) => OnePitBalance.FlowV3 &&
+            (h is HallBenchHost || h is GymBenchHost || h is GymV4BenchHost || h is PressV4Host);
+
+        public static Vector3 BeltMouth(Vector3 corner)
+        {
+            var pit = Game.Pit;
+            if (pit == null) return HallRowDefs.CombEnd;
+            var d = (corner - pit.Center).Flat();
+            if (d.sqrMagnitude < 0.001f) d = Vector3.back;
+            return pit.Center.Flat() + d.normalized * (pit.Radius + 0.25f);
+        }
+
+        /// Partial contributions to included children are refunded once, before any reentrant event.
+        public static void Include(string id)
+        {
+            var r = OnePitState.Circle(id);
+            if (r.Done) return;
+            double refund = r.Paid;
+            if (refund > 0 && Game.State == null) return;
+            r.Paid = 0;
+            r.Done = true;
+            if (refund > 0 && Game.State != null) Game.State.AddMoney(refund);
+        }
+
+        public static bool GymBundle(string id) => id == GymV4Defs.Bench2 || id == GymV4Defs.Bench3;
+        public static double GymPrice(string id)
+        {
+            int k = id == GymV4Defs.Bench2 ? 1 : 2;
+            return OnePitBalance.GymCirclePrice8d(id)
+                + OnePitBalance.GymCirclePrice8d(k == 1 ? GymV4Defs.Motor2 : GymV4Defs.Motor3)
+                + OnePitBalance.GymCirclePrice8d(k == 1 ? GymV4Defs.Track2 : GymV4Defs.Track3)
+                + OnePitBalance.GymCirclePrice8d(k == 1 ? GymV4Defs.Fans2 : GymV4Defs.Fans3);
+        }
+
+        public static void IncludeGym(int k)
+        {
+            Include(k == 1 ? GymV4Defs.Motor2 : GymV4Defs.Motor3);
+            Include(k == 1 ? GymV4Defs.Track2 : GymV4Defs.Track3);
+            Include(k == 1 ? GymV4Defs.Fans2 : GymV4Defs.Fans3);
+        }
+    }
+}
