+using UnityEngine;
+
+namespace Pitt.OnePit
+{
+    /// Full pool: pay and retire the oldest unowned plain duck when an expensive body arrives.
+    /// Credited is independent from Paid, which is also used to exclude held bodies from floor saves.
+    public static class V6nProdPool
+    {
+        static bool _settling;
+        public static int Replaced { get; private set; }
+        public static int Settled { get; private set; }
+        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
+        static void Reset() { _settling = false; Replaced = Settled = 0; }
+
+        public static bool Full => BodyBudget.Active &&
+            (Product.All.Count >= BodyBudget.AllCap || Product.FreeCount >= OnePitBalance.BudgetFreeCapNow);
+
+        public static bool MakeRoom(float incomingMultiplier, Product incoming = null)
+        {
+            if (!OnePitBalance.FlowV3 || incomingMultiplier < 2f || !Full || _settling) return false;
+            Product oldest = null;
+            var all = Product.All;
+            for (int i = 0; i < all.Count; i++)
+            {
+                var p = all[i];
+                if (!p || p == incoming || p.Zone != HallProdDefs.Zone || p.Kind != ProductKind.Duck ||
+                    p.State != ProductState.Resting || p.Credited || p.Paid || p.Lucky || p.LuckyUntil >= 0f ||
+                    p.Handler != ProductHandler.None || p.NoPickUntil > TimeCtl.GameTime ||
+                    !p.Body || p.Body.isKinematic || HallDropAll.IsLocked(p) || HallValue.Of(p) > 1.001f) continue;
+                if (oldest == null || p.Id < oldest.Id) oldest = p;
+            }
+            if (oldest == null || !Settle(oldest)) return false;
+            Replaced++;
+            return true;
+        }
+
+        /// Synchronous real payout. No direct AddMoney or speculative popup.
+        public static bool Settle(Product p)
+        {
+            if (_settling || !OnePitBalance.FlowV3 || Game.State == null || !Game.State.Hall ||
+                !p || !p.gameObject.activeSelf || p.Credited ||
+                (p.State != ProductState.Resting && p.State != ProductState.Spawned)) return false;
+            int id = p.Id;
+            var state = p.State;
+            _settling = true;
+            try
+            {
+                p.SetState(ProductState.Captured);
+                var at = Game.Pit != null ? Game.Pit.Center : p.transform.position;
+                Bus<ProductEnteredPit>.Pub(new ProductEnteredPit { P = p, Pos = at, By = ProductHandler.None });
+                if (!p || !p.gameObject.activeSelf || p.Id != id) return false;
+                if (!p.Credited) { p.SetState(state); return false; }
+                p.Despawn();
+                Settled++;
+                return true;
+            }
+            finally { _settling = false; }
+        }
+    }
+}
